// ============================================================
// ally-art.js  ―  味方キャラのAI生成立ち絵（純データ）
// ------------------------------------------------------------
// ★バンドル注意：全srcが1スコープを共有するため、ここはデータ定義のみ。
//   キー = キャラ id（yuito/ikuma/aoshi/tomoki/itsuki）、値 = 透過PNGの dataURL。
//   battle-scene.js の _drawAllies() が drawImageSprite() で遅延ロードし、
//   パーティ状態ストリップの真上に横並びで描画する（足元をストリップ上端に置く）。
//   アートが無い味方は描画しない（状態ストリップのみ）。
// ============================================================

var ALLY_ART = {
  yuito: "data:image/png;base64,",
  ikuma: "data:image/png;base64,",
  aoshi: "data:image/png;base64,",
  tomoki: "data:image/png;base64,",
  itsuki: "data:image/png;base64,"
};

(function (root, api) {
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  if (typeof window !== "undefined") root.SRPG = Object.assign(root.SRPG || {}, api);
})(typeof window !== "undefined" ? window : globalThis, { ALLY_ART: ALLY_ART });
